from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class NrbtsParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mcc, mnc = self.enb_ent_config['mcc'], self.enb_ent_config['mnc']
        self.set_parameter('mnc', mnc)
        self.set_parameter('mcc', mcc)
        self.set_parameter('mncLength', self.get_len_str(mnc))
        cu_type = self.enb_ent_config['cu_type'] if 'cu_type' in self.enb_ent_config else self.enb_ent_config['type']
        self.set_parameter('gNbCuType', cu_type)

        self.setup_optional(execution_config)
        self.setup_ips()
        self.setup_fullrack(execution_config)
        if not self.are_all_ecpri_72a():
            self.setup_optional_ecpri_72e()

    def are_all_ecpri_72a(self):
        for radio_num in self.enb_ent_config['radios'].keys():
            if not self.is_ecpri_72a(radio_num):
                return False
        return True

    def setup_optional_ecpri_72e(self):
        self.set_parameter('actCaOverloadCtrlEnh', 'true')
        self.set_parameter('actChannelMapVal', 'ShowAsWarning')
        self.set_parameter('actConnRrcPooling', 'false')
        self.set_parameter('actDDDSPeriodOptimization', 'true')
        self.set_parameter('actIntraFreqInterGnbMobilityNSA3x', 'true')
        self.set_parameter('actLteNrDss', 'false')
        self.set_parameter('actScheUePooling', 'false')
        self.set_parameter('actSliceAwareScheduler', 'false')
        self.set_parameter('actSlowPrbPooling', 'false')
        self.set_parameter('actSlowPrbPoolingFddFr1Enh', 'false')
        self.set_parameter('drbInactivityTimerSA', '600')
        self.set_parameter('drbInactivityTimerSA5qi1', '600')
        self.set_parameter('drbInactivityTimerSA5qi5', '600')
        self.set_parameter('drxDefaultPaging', 'v256')
        self.set_parameter('rrcReestabTypeSA', 'deactivated')
        self.set_parameter('slowPrbPoolFddFr1EnhCompMode', 'disabled')
        self.set_parameter('thpTimeCalc', 'disabled')

    def setup_optional(self, execution_config):
        self.set_parameter('actBbPoolExtensionTddFr1', 'true')
        self.set_parameter('actBbPoolTddFr1', 'true')
        self.set_parameter('actBbPoolTddFr1AlgEnh', 'true')
        self.set_parameter('actBbPoolTddFr1Enh', 'true')

        if execution_config['release'] >= 25.2:
            self.set_parameter('actBeamControlImprovement1', 'true')
            self.set_parameter('actBeamControlImprovement2', 'true')
            self.set_parameter('actHighestEstNrTputBcSel', 'true')
        else:
            self.set_parameter('actBeamControlImprovement1', 'false')
            self.set_parameter('actBeamControlImprovement2', 'false')
            self.set_parameter('actHighestEstNrTputBcSel', 'false')

        if execution_config['release'] >= 25.3:
            self.set_parameter('actBtcOvlProt', 'false')
            self.set_parameter('gnbOvlProtMode', 'classical')
            self.set_parameter('periodicalDataUsageReportTimer', '0')  # WA

        self.set_parameter('actChannelMapVal', 'Disabled')
        self.set_parameter('actConnRrcPooling', 'true')
        self.set_parameter('actDDDSPeriodOptimization', 'false')
        self.set_parameter('actEcpriPhase2', 'true')
        self.set_parameter('actEcpriPhase3', 'true')
        self.set_parameter('actFdmEnhancedScheduling', 'true')
        self.set_parameter('actFdmScheduling', 'true')
        self.set_parameter('actFr2L2DlTdMetricPreCalc8CC', 'false')

        self.set_parameter('actInactDetNSAUe', 'true')
        self.set_parameter('actIncXn', 'false')
        self.set_parameter('actIpThpt', 'true')
        self.set_parameter('actLteNrDss', 'true')
        # self.set_parameter('actMicroDTXAdvanced', 'true')
        self.set_parameter('actNgcFlexSaMode', 'true')
        self.set_parameter('actPaging', 'true')
        self.set_parameter('actRanSharing', 'true')
        self.set_parameter('actRanSharingEnh', 'disabled')
        # self.set_parameter('actRobustnessXnAndX2', 'false')
        self.set_parameter('actSACallProcessingDU', 'true')
        self.set_parameter('actScheUePooling', 'true')
        self.set_parameter('actSliceAwareScheduler', 'true')
        self.set_parameter('actSlowPrbPooling', 'true')
        self.set_parameter('actSlowPrbPoolingFddFr1Enh', 'true')
        self.set_parameter('actThpDist', 'true')
        self.set_parameter('actTimeAlignExtension', 'true')
        self.set_parameter('actTraceOvlProt', 'false')
        self.set_parameter('gNbIdLength', '24')
        # self.set_parameter('maxDlHarqTx', '4')
        # self.set_parameter('maxNumOfNonGBRBearers', '1280')
        # self.set_parameter('maxNumOfNonGBRBearersCGRPSA', '1280')
        # self.set_parameter('maxNumOfRrcCGRPSA', '640')
        # self.set_parameter('maxNumOfUsers', '1280')
        # self.set_parameter('maxUlHarqTx', '5')
        self.set_parameter('maxNumX2Links', '128')
        self.set_parameter('rejectSuppBcs', 'none')
        self.set_parameter('rrcReestabTypeSA', 'viaRRCSetup')

        # self.set_parameter('thpHistDownlinkMaxRange', '1000000')
        # self.set_parameter('thpHistDownlinkMinRange', '100')
        # self.set_parameter('thpHistScale', 'linear')
        # self.set_parameter('thpHistUplinkMaxRange', '100000')
        # self.set_parameter('thpHistUplinkMinRange', '100')
        self.set_parameter('thpTimeCalc', 'enabled')

        self.set_parameter('timerX2DataFwdGuard', '250')
        self.set_parameter('x2LinkSupervisionTmr', '0')

        self.set_parameter('tRLFindForDU', '2000ms')
        self.set_parameter('tRLFindForDUSA', '2000ms')

    def setup_ips(self):
        bts_id = self.enb_ent_config['id']
        self.set_struct_parameter('ngCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('ngUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('s1Uplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('x2Cplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('x2Uplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('xnCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')
        self.set_struct_parameter('xnUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1')

    def setup_fullrack(self, execution_config):
        if execution_config['is_fullrack']:
            self.set_parameter('actBtcOvlProt', 'false')
